    static Dictionary<ItemId, GunDef> byId;

    [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.SubsystemRegistration)]
    static void ResetStatics() => byId = null;

    // The stats a shot really has right now: the gun, changed by its enchant and your potions.
    public static GunDef Effective(GunDef g, EnchantDef e, Player p)
    {
        GunDef x = g.Clone();
        if (e != null)
        {
            if (e.element != Element.None) x.element = e.element;
            x.damage *= e.damage;
            x.cooldown *= e.rate;
            x.heat *= e.heat;
            x.range *= e.range;
            x.speed *= Mathf.Lerp(1f, e.range, 0.6f);
            x.lifesteal += e.lifesteal;
            x.crit += e.crit;
            x.hitBlast = Mathf.Max(x.hitBlast, e.hitBlast);
            x.chain += e.chain;
            x.pierce |= e.pierce;
            if (e.pellets > 0) { x.pellets += e.pellets; x.spread = Mathf.Max(x.spread, 3f); }
            x.spread *= e.spread;
            x.force += e.knock;
            x.structure *= e.structure;
            x.color = e.color;
        }
        if (p != null)
        {
            x.damage *= p.DamageDealtMul;
            x.cooldown *= p.FireRateMul;
            x.heat *= p.HeatMul;
        }
        return x;
    }

    // For the weapon info panel: the numbers, and a list of what's special about it.
    public static List<(string, string)> Stats(GunDef g)
    {
        var l = new List<(string, string)>();
        string mode = g.turret ? "Turret thrower" : g.strike > 0f ? "Airstrike" : g.mode == GunMode.Beam ? "Beam (hold)" : g.mode == GunMode.Projectile ? (g.blast > 0f ? "Explosive shots" : "Bullets that fly") : "Instant hit";
        l.Add(("TYPE", mode + (g.auto || g.mode == GunMode.Beam ? ", hold to fire" : ", click to fire")));
        int shots = Mathf.Max(1, g.pellets) * Mathf.Max(1, g.burst);
        string dmg = g.damage.ToString("0.#") + (shots > 1 ? "  x" + shots : "");
        l.Add(("DAMAGE", dmg + (g.mode == GunMode.Beam ? " per tick" : "")));
        float perSec = g.mode == GunMode.Beam ? 1f / Mathf.Max(0.01f, g.cooldown) : 1f / Mathf.Max(0.01f, g.cooldown);
        l.Add(("FIRE RATE", (g.mode == GunMode.Beam ? "constant" : perSec.ToString("0.0") + " shots/s") + (g.spinUp > 0f ? " (spins up)" : "")));
        float dps = g.damage * shots / Mathf.Max(0.01f, g.cooldown + (g.burst > 1 ? g.burstGap * (g.burst - 1) : 0f));
        l.Add(("DAMAGE / SEC", "~" + Mathf.RoundToInt(dps)));
        if (g.mode != GunMode.Projectile && !g.turret) l.Add(("RANGE", Mathf.RoundToInt(g.range) + " m"));
        if (g.blast > 0f) l.Add(("EXPLOSION", g.blast.ToString("0.#") + " m"));
        if (g.mag > 0) l.Add(("MAGAZINE", g.mag + " (reload " + g.reload.ToString("0.0") + "s)"));
        else if (g.heat > 0f) l.Add(("HEAT", Mathf.Max(1, Mathf.FloorToInt(100f / g.heat)) + " shots before overheating"));
        if (g.structure != 1f) l.Add(("VS LABS", "x" + g.structure.ToString("0.#") + " damage"));
        if (g.element != Element.None) l.Add(("ELEMENT", g.element.ToString().ToUpperInvariant()));
        var sp = new List<string>();
        if (g.charge > 0f) sp.Add("charge shot (hold, release: up to x" + (1f + g.chargeBonus).ToString("0.#") + ")");
        if (g.homing > 0f) sp.Add("homing");
        if (g.bounces > 0) sp.Add("bounces " + g.bounces + "x");
        if (g.ricochet > 0) sp.Add("ricochets " + g.ricochet + "x");
        if (g.pierce) sp.Add("pierces targets");
        if (g.wallPierce) sp.Add("shoots through walls");
        if (g.chain > 0) sp.Add("chains to " + g.chain + " more");
        if (g.cluster > 0) sp.Add(g.cluster + " cluster bombs");
        if (g.stick > 0f) sp.Add("sticky (" + g.stick.ToString("0.#") + "s fuse)");
        if (g.boomerang) sp.Add("boomerang");
        if (g.flak > 0f) sp.Add("airburst at " + Mathf.RoundToInt(g.flak) + " m");
        if (g.field > 0f) sp.Add(g.blackHole ? "black hole" : "leaves a damage zone");
        if (g.selfKnock > 0f) sp.Add("recoil jump");
        if (g.grapple) sp.Add("grappling hook");
        if (g.teleport) sp.Add("teleports you");
        if (g.puddle) sp.Add("slime puddles");
        if (g.lifesteal > 0f) sp.Add("heals you " + Mathf.RoundToInt(g.lifesteal * 100f) + "%");
        if (g.crit > 0f) sp.Add(Mathf.RoundToInt(g.crit * 100f) + "% crit");
        if (g.hitBlast > 0f) sp.Add("mini explosions");
        if (sp.Count > 0) l.Add(("SPECIAL", string.Join(", ", sp)));
        return l;
    }

    // The gun stats for this item (null = not one of the table guns).
    public static GunDef Get(ItemId id)
    {
        if (byId == null)
        {
            byId = new Dictionary<ItemId, GunDef>();
            foreach (GunDef g in All) byId[g.id] = g;
        }
        return byId.TryGetValue(id, out GunDef d) ? d : null;
    }
}
